ntent='Scramble';ctrlBar.appendChild(scrambleBtn);const infoBar=document.createElement('div');infoBar.style.margin='10px';container.appendChild(infoBar);const compSpan=document.createElement('span');compSpan.textContent='Comparisons: 0 ';infoBar.appendChild(compSpan);const swapSpan=document.createElement('span');swapSpan.textContent='Swaps: 0 ';infoBar.appendChild(swapSpan);const depthSpan=document.createElement('span');depthSpan.textContent='Call Depth: 0 ';infoBar.appendChild(depthSpan);const complexSpan=document.createElement('span');complexSpan.textContent=' Complexity: O(n²) ';infoBar.appendChild(complexSpan);function initArray(pattern){for(let i=0;i<ARR_SIZE;i++)data[i]=i+1;switch(pattern){case'Random':for(let i=ARR_SIZE-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[data[i],data[j]]=[data[j],data[i]];}break;case'Reverse':data.reverse();break;case'Nearly Sorted':for(let i=0;i<ARR_SIZE-2;i+=5){const j=i+Math.floor(Math.random()*5);[data[i],data[j]]=[data[j],data[i]];}break;}comparisons=swaps=0;updateCounters();draw();}function updateCounters(){compSpan.textContent='Comparisons: '+comparisons+' ';swapSpan.textContent='Swaps: '+swaps+' ';depthSpan.textContent='Call Depth: '+callDepth+' ';}function draw(){ctx.clearRect(0,0,W,H);if(workRange){ctx.fillStyle='rgba(0,255,0,0.1)';ctx.fillRect(workRange.low*barWidth,0,(workRange.high-workRange.low+1)*barWidth,H);}for(let i=0;i<ARR_SIZE;i++){let c='lightgray';if(highlight[i])c=highlight[i];ctx.fillStyle=c;ctx.fillRect(i*barWidth,H-data[i]/ARR_SIZE*H,barWidth-1,-data[i]/ARR_SIZE*H);}requestAnimationFrame(draw);}function setComplexity(){switch(algorithm){case'Bubble':complexSpan.textContent=' Complexity: O(n²) ';break;case'Quick':case'Merge':case'Heap':complexSpan.textContent=' Complexity: O(n log n) ';break;case'Radix':complexSpan.textContent=' Complexity: O(k·n) ';break;}}function* bubbleSort(){for(let i=0;i<ARR_SIZE;i++){for(let j=0;j<ARR_SIZE-i-1;j++){highlight[j]='red';highlight[j+1]='red';comparisons++;yield;highlight[j]=null;highlight[j+1]=null;if(data[j]>data[j+1]){[data[j],data[j+1]]=[data[j+1],data[j]];swaps++;highlight[j]='yellow';highlight[j+1]='yellow';yield;highlight[j]=null;highlight[j+1]=null;}}highlight[ARR_SIZE-i-1]='green';}for(let i=0;i<ARR_SIZE;i++)highlight[i]='green';}function* quickSort(lo,hi){if(lo<hi){callDepth++;workRange={low:lo,high:hi};let p=yield* partition(lo,hi);yield* quickSort(lo,p-1);yield* quickSort(p+1,hi);callDepth--;workRange=null;}}function* partition(lo,hi){let pivot=data[hi];highlight[hi]='blue';let i=lo-1;for(let j=lo;j<hi;j++){highlight[j]='red';comparisons++;yield;if(data[j]<pivot){i++;[data[i],data[j]]=[data[j],data[i]];swaps++;highlight[i]='yellow';highlight[j]='yellow';yield;highlight[i]=null;highlight[j]=null;}highlight[j]=null;}[data[i+1],data[hi]]=[data[hi],data[i+1]];swaps++;highlight[i+1]='yellow';highlight[hi]='yellow';yield;highlight[i+1]=null;highlight[hi]=null;highlight[hi]=null;return i+1;}function* mergeSort(l,r){if(l<r){callDepth++;let m=Math.floor((l+r)/2);workRange={low:l,high:r};yield* mergeSort(l,m);yield* mergeSort(m+1,r);yield* merge(l,m,r);callDepth--;workRange=null;}}function* merge(l,m,r){let left=data.slice(l,m+1);let right=data.slice(m+1,r+1);let i=0,j=0,k=l;while(i<left.length&&j<right.length){highlight[k]='red';comparisons++;yield;if(left[i]<=right[j]){data[k]=left[i];i++;}else{data[k]=right[j];j++;}swaps++;highlight[k]='yellow';yield;highlight[k]=null;k++;}while(i<left.length){highlight[k]='red';yield;data[k]=left[i];i++;swaps++;highlight[k]='yellow';yield;highlight[k]=null;k++;}while(j<right.length){highlight[k]='red';yield;data[k]=right[j];j++;swaps++;highlight[k]='yellow';yield;highlight[k]=null;k++;}}function* heapSort(){let n=ARR_SIZE;for(let i=Math.floor(n/2)-1;i>=0;i--)yield* heapify(n,i);for(let i=n-1;i>0;i--){[data[0],data[i]]=[data[i],data[0]];swaps++;highlight[0]='yellow';highlight[i]='yellow';yield;highlight[0]=null;highlight[i]=null;yield* heapify(i,0);}for(let i=0;i<ARR_SIZE;i++)highlight[i]