hange',e=>{mode=e.target.checked?'step':'continuous';if(mode==='step'){pause();stepBtn.disabled=false;}else{stepBtn.disabled=true;}});stepBtn.addEventListener('click',nextStep);scrambleBtn.addEventListener('click',()=>{initArray(scrambleSelect.value);});canvas.addEventListener('click',()=>{if(!running)start();});initArray('Random');setComplexity();draw();}
